/**
 * System logos -- the real logos of the systems Fightcade has channels for (Dreamcast, NES, ...)
 *
 * Small PNGs (from Wikimedia Commons, see assets/systems/SOURCES.md) shown in a rounded tile in the
 * Discover sidebar instead of coloured initials. A system with no logo here keeps its initials.
 * The logos live in this file because the updater only ships .js files: node tools/system-logos.js
 * rebuilds the LOGOS line from assets/systems/<key>.png.
 */
'use strict';

// Fightcade's system name -> the file key in assets/systems
const KEYS = {
    'Atomiswave': 'atomiswave', 'ColecoVision': 'colecovision', 'Dreamcast': 'dreamcast', 'Game Gear': 'gamegear',
    'MSX': 'msx', 'Master System': 'mastersystem', 'Megadrive': 'megadrive', 'NAOMI': 'naomi', 'NAOMI 2': 'naomi2',
    'NES': 'nes', 'PC-Engine': 'pcengine', 'PlayStation': 'playstation', 'Sega SG-1000': 'sg1000',
    'Super NES': 'snes', 'TurboGrafx16': 'turbografx16'
};
// LOGOS-START (generated by tools/system-logos.js, don't edit by hand)
const LOGOS = {"atomiswave":"","colecovision":"","dreamcast":"","gamegear":"","msx":"","mastersystem":"","megadrive":"","naomi":"","naomi2":"","nes":"","pcengine":"","playstation":"","sg1000":"","snes":"","turbografx16":""};
// LOGOS-END

const keyOf = (system) => KEYS[String(system || '').trim()] || '';
// a data: URL for the system's logo, or '' (then the caller keeps its own badge)
function url(system) {
    const k = keyOf(system);
    return k && LOGOS[k] ? 'data:image/png;base64,' + LOGOS[k] : '';
}

module.exports = {
    id: 'system-logos', name: 'System logos',
    start: () => api,
    KEYS, LOGOS, url, keyOf
};
const api = { url: (s) => url(s), has: (s) => !!url(s) };
